// Layout is generated by Graphviz locally. The editable DBML stays compatible with dbdiagram.io.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {pathToFileURL}=require('node:url');
const {instance}=require('../.runtime/dbml-tools/node_modules/@viz-js/viz');
const {chromium}=require('../frontend/node_modules/playwright');
const root=path.resolve(__dirname,'..'),out=path.join(root,'docs/dbdiagram/modules');
const manifest=JSON.parse(fs.readFileSync(path.join(out,'manifest.json'),'utf8'));
const schema=JSON.parse(fs.readFileSync(path.join(root,'docs/dbdiagram/schema-snapshot.json'),'utf8'));
const verified=JSON.parse(fs.readFileSync(path.join(out,'validation.json'),'utf8'));
const definitions=JSON.parse(fs.readFileSync(path.join(root,'docs/schema49-tables.json'),'utf8'));
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const q=s=>JSON.stringify(s);
const type=s=>s.replaceAll('character varying','varchar').replaceAll('timestamp with time zone','timestamptz');
const constraints=t=>schema.constraints.filter(c=>c.table_name===t);
function tableDot(m,name){
 const owned=m.owned_tables.includes(name),cons=constraints(name),all=schema.columns.filter(c=>c.table_name===name),cols=all.filter(c=>m.columns_shown[name].includes(c.name));
 const pks=new Set(cons.filter(c=>c.kind==='p').flatMap(c=>c.columns)),fks=new Set(cons.filter(c=>c.kind==='f').flatMap(c=>c.columns));
 const unique=new Set(cons.filter(c=>c.kind==='u'&&c.columns.length===1).flatMap(c=>c.columns));
 const rows=cols.map((c,i)=>{
  const flags=[pks.has(c.name)?'PK':'',fks.has(c.name)?'FK':'',unique.has(c.name)?'UQ':''].filter(Boolean).join(' ');
  return `<TR><TD WIDTH="45" ALIGN="LEFT" BGCOLOR="${i%2?'#F8FAFC':'#FFFFFF'}"><FONT FACE="Arial" POINT-SIZE="10" COLOR="#475569">${flags||'&#160;'}</FONT></TD><TD PORT="${c.name}" ALIGN="LEFT" BGCOLOR="${i%2?'#F8FAFC':'#FFFFFF'}"><FONT FACE="Arial" POINT-SIZE="14" COLOR="#172033">${pks.has(c.name)?'<B>':''}${esc(c.name)}${pks.has(c.name)?'</B>':''}</FONT></TD><TD ALIGN="LEFT" BGCOLOR="${i%2?'#F8FAFC':'#FFFFFF'}"><FONT FACE="Arial" POINT-SIZE="12" COLOR="#475569">${esc(type(c.type))}</FONT></TD><TD ALIGN="RIGHT" BGCOLOR="${i%2?'#F8FAFC':'#FFFFFF'}"><FONT FACE="Arial" POINT-SIZE="10" COLOR="#64748B">${c.not_null?'NN':'NULL'}</FONT></TD></TR>`;
 }).join('');
 const subtitle=owned?`Đầy đủ ${all.length} cột`:`THAM CHIẾU · rút gọn ${cols.length}/${all.length} cột`;
 const header=owned?m.color:'#64748B';
 return `${q(name)} [id=${q('table-'+name)},tooltip=${q(definitions.find(t=>t.name===name).description)},label=<<TABLE BORDER="1" COLOR="${owned?'#CBD5E1':'#CBD5E1'}" CELLBORDER="0" CELLSPACING="0" CELLPADDING="7"><TR><TD COLSPAN="4" PORT="header" ALIGN="LEFT" BGCOLOR="${header}"><FONT FACE="Arial" COLOR="#FFFFFF" POINT-SIZE="17"><B>${esc(name)}</B></FONT></TD></TR><TR><TD COLSPAN="4" ALIGN="LEFT" BGCOLOR="${owned?'#EFF6FF':'#F1F5F9'}"><FONT FACE="Arial" COLOR="#475569" POINT-SIZE="11">${subtitle}</FONT></TD></TR>${rows}</TABLE>>];`;
}
function graphDot(m,direction,positions){
 const selected=[...m.owned_tables,...m.context_tables];
 const lines=['digraph module {',`graph [rankdir=${direction},bgcolor="transparent",pad="0.30",nodesep="0.45",ranksep="0.85",splines=spline,outputorder=edgesfirst,fontname="Arial",newrank=true];`,'node [shape=plain,fontname="Arial"];','edge [fontname="Arial",fontsize=10,arrowsize=0.65,penwidth=1.0];'];
 for(const name of selected){let node=tableDot(m,name);if(positions){const p=positions.get(name);node=node.replace(' [',` [pos="${p.x},${p.y}!",pin=true,`)}lines.push(node)}
 for(const fk of schema.constraints.filter(c=>c.kind==='f'&&m.foreign_keys.includes(c.name))){
  assert.equal(fk.columns.length,1);assert.equal(fk.parent_columns.length,1);
  const keys=constraints(fk.table_name).filter(c=>['p','u'].includes(c.kind)).map(c=>c.columns);
  keys.push(...schema.indexes.filter(i=>i.table_name===fk.table_name&&i.is_unique&&!i.predicate&&i.columns.every(Boolean)).map(i=>i.columns));
  const unique=keys.some(k=>k.every(c=>fk.columns.includes(c)));
  const nullable=schema.columns.some(c=>c.table_name===fk.table_name&&fk.columns.includes(c.name)&&!c.not_null);
  const internal=m.owned_tables.includes(fk.parent_table),audit=fk.parent_table==='users';
  const attrs=[`id=${q('fk-'+fk.name)}`,`dir=both`,`arrowtail=${nullable?'teeodot':'teetee'}`,`arrowhead=${unique?'teeodot':'crowodot'}`,`color=${q(internal?m.color:'#94A3B8')}`,`tooltip=${q(fk.name+': '+fk.table_name+'.'+fk.columns[0]+' → '+fk.parent_table+'.'+fk.parent_columns[0])}`];
  if(audit)attrs.push('constraint=false');
  // Parent on the left/top, child on the right/bottom. Both endpoints are actual columns.
  lines.push(`${q(fk.parent_table)}:${fk.parent_columns[0]} -> ${q(fk.table_name)}:${fk.columns[0]} [${attrs.join(',')}];`);
 }
 lines.push('}');return lines.join('\n');
}
function dimensions(svg){const box=svg.match(/viewBox="([\d. -]+)"/)[1].split(/\s+/).map(Number);return {width:box[2],height:box[3]}}
function packedPositions(m,objects){
 const dims=new Map(objects.map(o=>[o.name,{width:Number(o.width)*72,height:Number(o.height)*72}]));
 function pack(names,cols,startX){
  const lanes=Array.from({length:cols},()=>({height:0,width:0,items:[]}));
  for(const name of names){const d=dims.get(name),lane=lanes.reduce((a,b)=>a.height<=b.height?a:b);lane.items.push({name,top:lane.height,...d});lane.height+=d.height+80;lane.width=Math.max(lane.width,d.width)}
  const result=[],x=[];for(let i=0;i<cols;i++)x.push(startX+lanes.slice(0,i).reduce((n,l)=>n+l.width+110,0));
  lanes.forEach((lane,i)=>lane.items.forEach(t=>result.push([t.name,{x:x[i]+t.width/2,y:-(t.top+t.height/2)}])));
  return {positions:result,width:lanes.reduce((n,l)=>n+l.width,0)+110*(cols-1)};
 }
 const refs=pack(m.context_tables,m.context_tables.length>7?2:1,0);
 const core=pack(m.owned_tables,m.owned_tables.length>9?4:m.owned_tables.length>4?3:2,refs.width+190);
 const map=new Map([...refs.positions,...core.positions]);
 for(const [a,ap]of map)for(const [b,bp]of map){if(a>=b)continue;const ad=dims.get(a),bd=dims.get(b);assert.ok(Math.abs(ap.x-bp.x)>=(ad.width+bd.width)/2||Math.abs(ap.y-bp.y)>=(ad.height+bd.height)/2,'Packed table overlap '+a+' '+b)}
 return map;
}
(async()=>{
 assert.equal(verified.all_passed,true);
 const viz=await instance(),browser=await chromium.launch({channel:'chrome',headless:true});
 const results=[];
 try{
  const page=await browser.newPage({viewport:{width:1440,height:1000}}),errors=[];page.on('pageerror',e=>errors.push(e.message));
  for(const m of manifest.modules){
   const baseline=graphDot(m,'LR'),objects=viz.renderJSON(baseline,{engine:'dot'}).objects;
   const fixed=graphDot(m,'LR',packedPositions(m,objects)),fixedSvg=viz.renderString(fixed,{format:'svg',engine:'nop2'}),fixedSize=dimensions(fixedSvg);
   const candidates=[{direction:'packed-grid',dot:fixed,svg:fixedSvg,...fixedSize,score:Math.min(1500/fixedSize.width,950/fixedSize.height)},...['LR','TB'].map(direction=>{const dot=graphDot(m,direction),svg=viz.renderString(dot,{format:'svg',engine:'dot'}),size=dimensions(svg);return {direction,dot,svg,...size,score:Math.min(1500/size.width,950/size.height)}})].sort((a,b)=>b.score-a.score);
   const rendered=candidates[0];
   fs.writeFileSync(path.join(out,m.slug+'.dot'),rendered.dot+'\n');fs.writeFileSync(path.join(out,m.slug+'.svg'),rendered.svg);
   const width=Math.ceil(Math.max(rendered.width+96,1100)),height=Math.ceil(rendered.height+340);
   const html=`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>${esc(m.title)}</title><style>@page{size:${width}px ${height}px;margin:0}*{box-sizing:border-box}body{margin:0;background:#fff;color:#172033;font:16px Arial,sans-serif}.sheet{width:${width}px;height:${height}px;position:relative;padding:38px 48px}header{height:160px;border-bottom:2px solid #e2e8f0}.number{color:${m.color};font-weight:bold;letter-spacing:2px;font-size:15px}h1{font-size:34px;margin:12px 0}header p{margin:0;color:#475569;font-size:17px}.legend{display:flex;gap:22px;margin-top:16px;font-size:14px;color:#475569}.swatch{display:inline-block;width:13px;height:13px;border-radius:2px;margin-right:7px;vertical-align:-2px}.diagram{position:absolute;left:${(width-rendered.width)/2}px;top:210px;width:${rendered.width}px;height:${rendered.height}px}footer{position:absolute;left:48px;right:48px;bottom:26px;border-top:1px solid #e2e8f0;padding-top:14px;font-size:13px;line-height:1.65;color:#475569}footer p{margin:0}</style></head><body><main class="sheet"><header><div class="number">SƠ ĐỒ CSDL ${String(m.number).padStart(2,'0')} / 08 · model49 / V13</div><h1>${esc(m.title)}</h1><p>${m.owned_tables.length} bảng chính đầy đủ · ${m.owned_columns} cột chính · ${m.context_tables.length} bảng tham chiếu rút gọn · ${m.foreign_keys.length} FK có nguồn trong nhóm</p><div class="legend"><span><i class="swatch" style="background:${m.color}"></i>Bảng chính: đủ cột</span><span><i class="swatch" style="background:#64748B"></i>Bảng ngoài nhóm: rút gọn, chỉ để đọc FK</span></div></header><img class="diagram" src="${m.slug}.svg" alt="Sơ đồ ${esc(m.title)}"><footer><p>PK: khóa chính · FK: khóa ngoại · UQ: unique một cột · NN: NOT NULL. Cột NULL cho phép thiếu giá trị; tên và kiểu giữ theo PostgreSQL.</p><p>Quan hệ: chân quạ = nhiều; vòng tròn = có thể không có; vạch = một. Từ bảng tham chiếu không mở rộng thêm quan hệ.</p><p>Nguồn: metadata PostgreSQL đã đối chiếu ${manifest.schema_verified_on}. DBML đầy đủ: docs/quanlytro.dbml. PDF/SVG phần này dựng bằng Graphviz, không phải bản xuất web dbdiagram.io.</p></footer></main></body></html>`;
   fs.writeFileSync(path.join(out,m.slug+'.html'),html);
   await page.goto(pathToFileURL(path.join(out,m.slug+'.html')).href,{waitUntil:'load'});await page.evaluate(()=>document.fonts.ready);
   assert.equal(await page.locator('.diagram').evaluate(img=>img.complete&&img.naturalWidth>0),true,m.slug+' SVG load');
   const sizes=await page.evaluate(()=>({head:document.querySelector('header').getBoundingClientRect().bottom,image:document.querySelector('.diagram').getBoundingClientRect(),footer:document.querySelector('footer').getBoundingClientRect().top}));
   assert.ok(sizes.head<sizes.image.top&&sizes.image.bottom<sizes.footer,m.slug+' poster sections overlap');
   await page.pdf({path:path.join(out,m.slug+'.pdf'),preferCSSPageSize:true,printBackground:true,timeout:60000});
   await page.setViewportSize({width,height});await page.screenshot({path:path.join(out,m.slug+'.png'),timeout:60000});
   results.push({slug:m.slug,renderer:'Graphviz via @viz-js/viz 3.31.0; Chromium PDF',direction:rendered.direction,width,height,owned_tables:m.owned_tables.length,reference_copies:m.context_tables.length,columns_shown:Object.values(m.columns_shown).reduce((n,c)=>n+c.length,0),foreign_keys:m.foreign_keys.length,poster_sections_do_not_overlap:true});
   console.log(JSON.stringify(results.at(-1)));
  }
  assert.equal(errors.length,0);fs.writeFileSync(path.join(out,'render-validation.json'),JSON.stringify({schema_verified_on:manifest.schema_verified_on,js_errors:errors,modules:results,all_passed:true},null,2)+'\n');
 }finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
